BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE ROLE access_request NOINHERIT; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE access_worker NOINHERIT; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organisations(id uuid PRIMARY KEY,name text NOT NULL);
CREATE TABLE IF NOT EXISTS referrals(id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES organisations(id),state text NOT NULL CHECK(state IN('RECEIVED','IDENTITY_PENDING','ADMIN_PENDING','READY','DISPATCH_PENDING','RECONCILING','COMPLETED','EXCEPTION','REJECTED')),version integer NOT NULL DEFAULT 0,identity_status text,extraction jsonb,policy_decision jsonb,external_id text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE IF NOT EXISTS artifacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES organisations(id),referral_id uuid NOT NULL,object_key text NOT NULL,digest_sha256 text NOT NULL CHECK(length(digest_sha256)=64),media_type text NOT NULL,size_bytes bigint NOT NULL,scan_status text NOT NULL CHECK(scan_status IN('CLEAN','REJECTED')),encryption_key_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,referral_id) REFERENCES referrals(tenant_id,id),UNIQUE(tenant_id,referral_id,digest_sha256));
CREATE TABLE IF NOT EXISTS commands(tenant_id uuid NOT NULL REFERENCES organisations(id),command_id uuid NOT NULL,referral_id uuid NOT NULL,result_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,command_id));
CREATE TABLE IF NOT EXISTS evidence_events(id bigint GENERATED ALWAYS AS IDENTITY,tenant_id uuid NOT NULL REFERENCES organisations(id),referral_id uuid NOT NULL,sequence integer NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,previous_hash text NOT NULL,hash text NOT NULL,correlation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,referral_id,sequence));
CREATE TABLE IF NOT EXISTS work_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES organisations(id),referral_id uuid NOT NULL,kind text NOT NULL,status text NOT NULL CHECK(status IN('OPEN','RESOLVED')),reason text NOT NULL,evidence jsonb NOT NULL DEFAULT '{}',resolution jsonb,resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS executions(id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES organisations(id),referral_id uuid NOT NULL,status text NOT NULL,attempts integer NOT NULL DEFAULT 0,external_id text,last_error text,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id));
CREATE TABLE IF NOT EXISTS outbox(id bigint GENERATED ALWAYS AS IDENTITY,tenant_id uuid NOT NULL REFERENCES organisations(id),referral_id uuid NOT NULL,aggregate_version integer NOT NULL,execution_id uuid NOT NULL,payload jsonb NOT NULL,correlation_id uuid NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','LEASED','DONE','POISON')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,execution_id));
CREATE INDEX IF NOT EXISTS outbox_claim ON outbox(status,available_at,lease_until,id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['referrals','artifacts','commands','evidence_events','work_items','executions','outbox'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t);END LOOP;END $$;
GRANT USAGE ON SCHEMA public TO access_request,access_worker;
GRANT SELECT ON organisations TO access_request,access_worker;
GRANT SELECT,INSERT,UPDATE ON referrals,artifacts,commands,evidence_events,work_items TO access_request;
GRANT SELECT ON executions,outbox TO access_request;
GRANT SELECT,INSERT,UPDATE ON referrals,commands,evidence_events,work_items,executions,outbox TO access_worker;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO access_request,access_worker;
INSERT INTO schema_migrations(version) VALUES('0001_access') ON CONFLICT DO NOTHING;
COMMIT;
